// HasSlackAppInstall applies the HasEdge predicate on the "slack_app_install" edge.
func HasSlackAppInstall() predicate.SlackAppUser {
	return predicate.SlackAppUser(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.To(SlackAppInstallTable, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, SlackAppInstallTable, SlackAppInstallColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasSlackAppInstallWith applies the HasEdge predicate on the "slack_app_install" edge with a given conditions (other predicates).
func HasSlackAppInstallWith(preds ...predicate.SlackAppInstall) predicate.SlackAppUser {
	return predicate.SlackAppUser(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.To(SlackAppInstallInverseTable, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, SlackAppInstallTable, SlackAppInstallColumn),
		)
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.SlackAppUser) predicate.SlackAppUser {
	return predicate.SlackAppUser(func(s *sql.Selector) {
		s1 := s.Clone().SetP(nil)
		for _, p := range predicates {
			p(s1)
		}
		s.Where(s1.P())
	})
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.SlackAppUser) predicate.SlackAppUser {
	return predicate.SlackAppUser(func(s *sql.Selector) {
		s1 := s.Clone().SetP(nil)
		for i, p := range predicates {
			if i > 0 {
				s1.Or()
			}
			p(s1)
		}
		s.Where(s1.P())
	})
}

// Not applies the not operator on the given predicate.
func Not(p predicate.SlackAppUser) predicate.SlackAppUser {
	return predicate.SlackAppUser(func(s *sql.Selector) {
		p(s.Not())
	})
}
